public class TestStatementsController extends TestStatementsCommon {

	private final StatementsController controller = new StatementsController();

	@BeforeEach
	public void initMocks() {
		request.setMethod(HttpMethod.POST.name());

		super.initMocks();
	}

	@Test
	public void shouldUseTimeoutParameterForUpdateQueries() throws Exception {
		final int maxExecution = 1;
		request.setContentType(Protocol.SPARQL_UPDATE_MIME_TYPE);
		request.addParameter(Protocol.TIMEOUT_PARAM_NAME, String.valueOf(maxExecution));
		final String updateString = "delete where { <monkey:pod> ?p ?o . }";
		request.setContent(updateString.getBytes(StandardCharsets.UTF_8));

		final Update updateMock = Mockito.mock(Update.class);
		Mockito.when(connectionMock.prepareUpdate(QueryLanguage.SPARQL, updateString, null)).thenReturn(updateMock);

		// act
		controller.handleRequest(request, response);

		Mockito.verify(updateMock).setMaxExecutionTime(maxExecution);
	}

	@Test
	public void shouldThrowDescriptiveErrorOnEmpryUpdateQueries_SparqlUpdateMimeType() {
		request.setContentType(Protocol.SPARQL_UPDATE_MIME_TYPE);
		request.addParameter(Protocol.UPDATE_PARAM_NAME, "");
		Exception exception = Assertions.assertThrows(ClientHTTPException.class, () -> {
			controller.handleRequest(request, response);
		});
		assertTrue(exception.getMessage().contains("Updates must be non-empty"));
	}

	@Test
	public void shouldThrowDescriptiveErrorOnEmptyUpdateQueries_FormMimeType() {
		request.setContentType(Protocol.FORM_MIME_TYPE);
		request.addParameter(Protocol.UPDATE_PARAM_NAME, "");
		Exception exception = Assertions.assertThrows(ClientHTTPException.class, () -> {
			controller.handleRequest(request, response);
		});
		assertTrue(exception.getMessage().contains("Updates must be non-empty"));
	}

	@Test
	public void shouldMapDecoderMemoryLimitToPayloadTooLarge() throws Exception {
		request.setContentType(RDFFormat.TURTLE.getDefaultMIMEType());
		request.setContent("<urn:s> <urn:p> <urn:o> .".getBytes(StandardCharsets.UTF_8));
		RDFInputDecompressionLimitException limit = decoderMemoryLimit();
		RDFParseException parseException = new RDFParseException(limit.getMessage());
		parseException.initCause(limit);
		Mockito.doThrow(parseException)
				.when(connectionMock)
				.add(Mockito.any(InputStream.class), Mockito.any(), Mockito.eq(RDFFormat.TURTLE),
						Mockito.any(Resource[].class));

		ClientHTTPException exception = assertThrows(ClientHTTPException.class,
				() -> controller.handleRequest(request, response));

		assertEquals(413, exception.getStatusCode());
	}

	private static RDFInputDecompressionLimitException decoderMemoryLimit() throws IOException {
		String previous = System.getProperty(RioCompression.MAX_DECODER_MEMORY_KIB_PROPERTY);
		System.setProperty(RioCompression.MAX_DECODER_MEMORY_KIB_PROPERTY, "1");
		try {
			ByteArrayOutputStream compressed = new ByteArrayOutputStream();
			try (XZOutputStream outputStream = new XZOutputStream(compressed, new LZMA2Options())) {
				outputStream.write("data".getBytes(StandardCharsets.UTF_8));
			}
			return assertThrows(RDFInputDecompressionLimitException.class,
					() -> RioCompression.decompressIfDetected(
							new ByteArrayInputStream(compressed.toByteArray())).readAllBytes());
		} finally {
			if (previous == null) {
				System.clearProperty(RioCompression.MAX_DECODER_MEMORY_KIB_PROPERTY);
			} else {
				System.setProperty(RioCompression.MAX_DECODER_MEMORY_KIB_PROPERTY, previous);
			}
		}
	}
}
